def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([3, 3, 3]), fmt([1, 2, 3, 4]), fmt([4, 3, 2, 1]), fmt([2, 4, 5, 2, 1, 9, 3, 2, 2, 5, 1, 5]),
             fmt([-5, 5, -5, 5, 0]), fmt([10**9, -10**9, 10**9, -10**9, 0])]
    for n in (2, 4, 6, 9, 12, 20, 30, 40):
        for _ in range(3):
            hi = rng.choice([2, 3, 5, 10])
            tests.append(fmt([rng.randint(-hi, hi) for _ in range(n)]))
    n = 100000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(n)]))
    tests.append(fmt([rng.randint(-5, 5) for _ in range(n)]))
    tests.append(fmt([rng.randint(-1000, 1000) for _ in range(n)]))
    tests.append(fmt([7] * n))
    return tests
